using System;using System.IO;using System.Threading.Tasks;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using RoadGunner;
public static class ConceptCombatCapture {
 static async Task Wait(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)await Task.Delay(10);}
 public static async Task<string> Main(){if(!EditorApplication.isPlaying)throw new Exception("Enter Play");var s=UnityEngine.Object.FindAnyObjectByType<GameSession>();var axis=Quaternion.Euler(0,45,0);s.vehicle.Body.constraints=RigidbodyConstraints.None;foreach(var r in s.spawns.pool)r.enabled=true;foreach(var b in s.spawns.buggyPool){b.enabled=true;b.AIEnabled=true;b.gun.enabled=true;}s.spawns.enabled=true;s.turret.enabled=true;s.Restart();s.health.DamageEnabled=true;s.input.testInput=true;s.input.testBrake=true;s.input.testDirection=Vector2.zero;s.vehicle.ResetPose(axis*new Vector3(-2.5f,.7f,-57.5f),Quaternion.Euler(0,90,0));s.follow.Snap();await Wait(.65f);var src=s.follow.GetComponent<Camera>();var g=new GameObject("Temporary live gameplay capture");var cam=g.AddComponent<Camera>();cam.CopyFrom(src);cam.enabled=false;cam.aspect=720f/1280;cam.GetUniversalAdditionalCameraData().renderPostProcessing=src.GetUniversalAdditionalCameraData().renderPostProcessing;var rt=new RenderTexture(720,1280,24);rt.antiAliasing=2;rt.Create();var canvas=s.hud.GetComponentInParent<Canvas>();var oldMode=canvas.renderMode;var oldCamera=canvas.worldCamera;float plane=canvas.planeDistance;var old=RenderTexture.active;string folder="/Users/arthuri/Documents/Codex/2026-10-09/macbook-app-store/outputs/concept-overhaul-2026-10-16/";
 Action<string> save=label=>{cam.transform.SetPositionAndRotation(src.transform.position,src.transform.rotation);Canvas.ForceUpdateCanvases();RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(720,1280,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,720,1280),0,0);t.Apply();File.WriteAllBytes(folder+label+".png",t.EncodeToPNG());UnityEngine.Object.Destroy(t);};
 try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;int shots=s.turret.ShotsFired;s.input.testBrake=false;s.input.testDirection=new Vector2(.707f,.707f)*.50f;float end=Time.realtimeSinceStartup+7;while(s.turret.ShotsFired<shots+2&&Time.realtimeSinceStartup<end)await Task.Delay(10);save("final-live-combat");s.input.testBrake=true;s.input.testDirection=Vector2.zero;var h=s.vehicle.GetComponent<HarpoonCollector>();end=Time.realtimeSinceStartup+7;while(h.State!=HarpoonState.Retracting&&Time.realtimeSinceStartup<end)await Task.Delay(10);save("final-live-harpoon");return "Live input/combat captures; shots="+(s.turret.ShotsFired-shots)+", kills="+s.Kills+", harpoon="+h.State;}
 finally{canvas.renderMode=oldMode;canvas.worldCamera=oldCamera;canvas.planeDistance=plane;RenderTexture.active=old;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(g);s.input.testInput=false;s.input.testDirection=Vector2.zero;s.input.testBrake=false;s.Restart();s.follow.Snap();}}
}
